'use strict';
const KEY='maintenance-practice-225-v1';
const categories=[...new Set(QUESTIONS.map(q=>q.category))];
let storageWorks=true;
let state={answers:{},flags:[],index:0,submitted:false};
try{const saved=JSON.parse(localStorage.getItem(KEY));if(saved&&typeof saved==='object'){state.index=Number.isInteger(saved.index)&&saved.index>=0&&saved.index<225?saved.index:0;state.submitted=saved.submitted===true;state.flags=Array.isArray(saved.flags)?saved.flags.filter(i=>Number.isInteger(i)&&i>=0&&i<225):[];for(const [id,value]of Object.entries(saved.answers||{})){if(/^\d+$/.test(id)&&+id>=1&&+id<=225&&Number.isInteger(value)&&value>=0&&value<4)state.answers[id]=value;}}}catch{storageWorks=false;}
const root=document.querySelector('#app');
const escapeHtml=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const answered=()=>Object.keys(state.answers).length;
function save(){try{localStorage.setItem(KEY,JSON.stringify(state));storageWorks=true;}catch{storageWorks=false;}}
function countCategory(category){return QUESTIONS.filter(q=>q.category===category&&state.answers[q.id]!==undefined).length;}
function results(){const correct=QUESTIONS.filter(q=>state.answers[q.id]===q.answer).length;return{correct,wrong:answered()-correct,unanswered:225-answered(),percentage:Math.round(correct/225*1000)/10};}
function go(index,focus=true){state.index=Math.max(0,Math.min(224,index));save();render();if(focus){document.querySelector('.question').focus();document.querySelector('.status-bar').scrollIntoView({behavior:'smooth',block:'start'});}}
function render(){if(state.submitted){renderResults();return;}const q=QUESTIONS[state.index];const ci=categories.indexOf(q.category);root.innerHTML=`<div class="workspace"><aside class="sidebar" aria-label="Question categories"><h2>Assessment sections</h2>${categories.map((c,i)=>`<button class="topic ${c===q.category?'active':''}" data-category="${i}" ${c===q.category?'aria-current="true"':''}>${escapeHtml(c)}<span>${countCategory(c)}/15</span></button>`).join('')}<p class="legend">15 sections · 15 questions each<br>No time limit</p></aside><section aria-label="Assessment"><label class="sr-only" for="topic-select">Go to section</label><select id="topic-select" class="mobile-topics">${categories.map((c,i)=>`<option value="${i}" ${i===ci?'selected':''}>${i+1}. ${escapeHtml(c)} (${countCategory(c)}/15)</option>`).join('')}</select><div class="status-bar"><p><strong>${answered()}</strong> of 225 answered</p><button class="quiet" id="submit-top">Submit assessment</button></div><progress value="${answered()}" max="225" aria-label="Questions answered"></progress><article class="question-card"><div class="question-meta"><span>${escapeHtml(q.category)}</span><span>Question ${q.id} / 225</span></div><h2 class="question" tabindex="-1" id="question-label">${escapeHtml(q.question)}</h2><fieldset aria-labelledby="question-label">${q.options.map((o,i)=>`<label class="option"><input type="radio" name="answer" value="${i}" ${state.answers[q.id]===i?'checked':''}><span class="letter">${'ABCD'[i]}</span><span>${escapeHtml(o)}</span></label>`).join('')}</fieldset><div class="nav-row"><button id="prev" ${state.index===0?'disabled':''}>Previous</button><button id="flag" class="${state.flags.includes(state.index)?'flagged':'quiet'}" aria-pressed="${state.flags.includes(state.index)}">${state.flags.includes(state.index)?'Flagged for review':'Flag for review'}</button><button id="next" class="primary">${state.index===224?'Submit assessment':'Next question'}</button></div></article><p class="storage" aria-live="polite">${storageWorks?'Progress saved on this device. You can leave and return.':'Browser storage is unavailable. Keep this page open to retain your answers.'}</p><details class="map"><summary>Question navigator · ${state.flags.length} flagged</summary><div class="grid">${QUESTIONS.map((item,i)=>`<button data-go="${i}" aria-label="Question ${item.id}${state.answers[item.id]!==undefined?', answered':', unanswered'}${state.flags.includes(i)?', flagged':''}" class="${state.answers[item.id]!==undefined?'answered ':''}${i===state.index?'current ':''}${state.flags.includes(i)?'marked':''}">${item.id}</button>`).join('')}</div><p class="legend">Green: answered · Blue outline: current · Gold underline: flagged</p><div class="actions"><button class="quiet" id="first-unanswered">Go to first unanswered</button><button class="quiet" id="restart-button">Start again</button></div></details></section></div>`;
root.querySelectorAll('[data-category]').forEach(b=>b.onclick=()=>go(+b.dataset.category*15));root.querySelector('#topic-select').onchange=e=>go(+e.target.value*15);
root.querySelectorAll('input[name="answer"]').forEach(input=>input.onchange=()=>{state.answers[q.id]=+input.value;save();const mapOpen=root.querySelector('.map').open;render();root.querySelector('.map').open=mapOpen;root.querySelector(`input[value="${input.value}"]`).focus();});
root.querySelector('#prev').onclick=()=>go(state.index-1);root.querySelector('#next').onclick=()=>state.index===224?submitPrompt():go(state.index+1);root.querySelector('#submit-top').onclick=submitPrompt;
root.querySelector('#flag').onclick=()=>{state.flags=state.flags.includes(state.index)?state.flags.filter(i=>i!==state.index):[...state.flags,state.index];save();render();root.querySelector('#flag').focus();};
root.querySelectorAll('[data-go]').forEach(b=>b.onclick=()=>go(+b.dataset.go));root.querySelector('#first-unanswered').onclick=()=>{const i=QUESTIONS.findIndex(q=>state.answers[q.id]===undefined);if(i>=0)go(i);else submitPrompt();};root.querySelector('#restart-button').onclick=()=>document.querySelector('#restart').showModal();}
function submitPrompt(){const remaining=225-answered();document.querySelector('#confirm-text').textContent=remaining?`You have answered ${answered()} of 225 questions. The ${remaining} unanswered questions will receive zero points. You can return to complete them or submit now.`:'You have answered all 225 questions. Submit to view your score, topic breakdown and answer explanations.';document.querySelector('#confirm').showModal();}
document.querySelector('#confirm').addEventListener('close',e=>{if(e.target.returnValue==='submit'){state.submitted=true;save();render();window.scrollTo({top:0,behavior:'smooth'});root.querySelector('#result-title').focus();}});
document.querySelector('#restart').addEventListener('close',e=>{if(e.target.returnValue==='restart'){state={answers:{},flags:[],index:0,submitted:false};save();render();window.scrollTo({top:0,behavior:'smooth'});}});
function renderResults(){const r=results();root.innerHTML=`<section class="results-card" aria-label="Assessment result"><div class="result-top"><div class="score" style="--score:${r.percentage}"><div class="score-inner"><strong>${r.percentage}%</strong><span>overall score</span></div></div><div><p class="eyebrow">ASSESSMENT COMPLETE</p><h2 id="result-title" tabindex="-1">Your practice result</h2><p>You scored <strong>${r.correct} out of 225</strong>.</p><p>Review the explanations below and focus on your lowest-scoring sections.</p></div></div><div class="metrics"><div><strong>${r.correct}</strong><span>Correct</span></div><div><strong>${r.wrong}</strong><span>Incorrect</span></div><div><strong>${r.unanswered}</strong><span>Unanswered</span></div></div><h3>Performance by section</h3><div class="breakdown">${categories.map(c=>{const score=QUESTIONS.filter(q=>q.category===c&&state.answers[q.id]===q.answer).length;return`<div class="category-score"><p><span>${escapeHtml(c)}</span><strong>${score}/15</strong></p><progress value="${score}" max="15" aria-label="${escapeHtml(c)}: ${score} of 15"></progress></div>`;}).join('')}</div><div class="actions"><button class="primary" id="retry">New attempt</button><button id="print">Print / save result as PDF</button></div></section><div class="review-heading"><h2>Answers & explanations</h2><label for="review-filter">Show <select id="review-filter" class="review-filter"><option value="all">All 225 questions</option><option value="incorrect">Incorrect & unanswered</option><option value="correct">Correct answers</option><option value="flagged">Flagged questions</option></select></label></div><div id="review"></div>`;root.querySelector('#retry').onclick=()=>document.querySelector('#restart').showModal();root.querySelector('#print').onclick=()=>window.print();root.querySelector('#review-filter').onchange=e=>renderReview(e.target.value);renderReview('all');}
function renderReview(filter){const selected=QUESTIONS.filter((q,i)=>filter==='all'||filter==='correct'&&state.answers[q.id]===q.answer||filter==='incorrect'&&state.answers[q.id]!==q.answer||filter==='flagged'&&state.flags.includes(i));root.querySelector('#review').innerHTML=selected.length?selected.map(q=>{const chosen=state.answers[q.id];const correct=chosen===q.answer;return`<article class="review-item ${correct?'':'wrong'}"><div class="review-meta">${q.id} / 225 · ${escapeHtml(q.category)} · ${correct?'Correct':chosen===undefined?'Unanswered':'Incorrect'}</div><h3>${escapeHtml(q.question)}</h3><p>Your answer: <strong>${chosen===undefined?'Not answered':escapeHtml(q.options[chosen])}</strong></p>${correct?'':`<p>Correct answer: <strong>${escapeHtml(q.options[q.answer])}</strong></p>`}<p class="explanation">${escapeHtml(q.explanation)}</p></article>`;}).join(''):'<p>No questions in this view.</p>';}
render();
